-- Reading: True/False/Not given, matching headings and summary completion
-- questions (english-reading.ts) for six library texts, authored in
-- supabase/content/english/reading. Appended after the existing multiple-choice
-- questions; a question whose id the article already has is skipped, so this is
-- idempotent and never overwrites an admin's edits. Older reading-articles code
-- ignores the new types, so it is safe before or after the function deploy.

with additions(slug, questions) as (
  values
    ('a2-the-evening-the-lights-went-out', '[{"id": "t1", "type": "tfng", "prompt": "The lights went out on a summer evening.", "answer": "false", "explanation": "\"Last winter, on a cold evening in January\".", "skill": "reading.detail"}, {"id": "t2", "type": "tfng", "prompt": "The writer''s phone battery was almost empty.", "answer": "true", "explanation": "\"My phone had only ten per cent battery.\"", "skill": "reading.detail"}, {"id": "t3", "type": "tfng", "prompt": "Uncle Rustam repaired the electricity.", "answer": "not_given", "explanation": "Uncle Rustam had a torch and checked on everyone. The text does not say who repaired the electricity.", "skill": "reading.detail"}]'::jsonb),
    ('b1-my-first-job-as-a-junior-developer', '[{"id": "t1", "type": "tfng", "prompt": "The writer studied programming at university.", "answer": "false", "explanation": "\"I had studied programming online for two years.\"", "skill": "reading.detail"}, {"id": "t2", "type": "tfng", "prompt": "Android users could not log in because of the writer''s change.", "answer": "true", "explanation": "\"Nobody on Android could log in for almost an hour.\"", "skill": "reading.detail"}, {"id": "t3", "type": "tfng", "prompt": "Dilshod has worked at the company for many years.", "answer": "not_given", "explanation": "The text says Dilshod is the team lead and the writer''s mentor, but not how long he has worked there.", "skill": "reading.detail"}, {"id": "h1", "type": "headings", "prompt": "Choose the best heading for each paragraph. There are more headings than paragraphs.", "options": ["Learning by being asked", "Moving to a bigger company", "A small fix, a big problem", "Don''t stay silent", "Not as ready as I thought", "Why I almost quit programming", "A meeting I expected to end badly"], "items": [{"paragraph": 1, "answer_index": 4}, {"paragraph": 2, "answer_index": 2}, {"paragraph": 3, "answer_index": 6}, {"paragraph": 4, "answer_index": 0}, {"paragraph": 5, "answer_index": 3}], "explanation": "1: \"I thought I was ready. I wasn''t.\" 2: a simple bug fix stopped Android logins. 3: he was sure he would be fired. 4: Dilshod asks questions until he finds the answer. 5: \"Don''t be afraid to ask questions.\"", "skill": "reading.main_idea"}, {"id": "g1", "type": "gap", "prompt": "Complete the summary. Use ONE word from the text in each gap.", "text": "After a bug in his first week, the writer expected to be ___, but his team lead helped him write a ___ that he still uses. Now they look at his code together every ___.", "answers": [["fired"], ["checklist"], ["friday", "fridays"]], "explanation": "Paragraph 3: \"I was sure he was going to fire me… we wrote a checklist.\" Paragraph 4: \"Every Friday, we spend thirty minutes looking at my code.\"", "skill": "reading.detail"}]'::jsonb),
    ('b1-why-more-people-are-cycling-to-work', '[{"id": "t1", "type": "tfng", "prompt": "With a bike-sharing scheme, you can rent a bike using a phone app.", "answer": "true", "explanation": "\"…bike-sharing schemes, where you can rent a bike with a phone app for a short trip.\"", "skill": "reading.detail"}, {"id": "t2", "type": "tfng", "prompt": "Electric bikes are cheaper than normal bikes.", "answer": "not_given", "explanation": "The text says electric bikes make longer or hillier journeys possible, but says nothing about their price.", "skill": "reading.detail"}, {"id": "t3", "type": "tfng", "prompt": "Doctors disagree about whether exercise is good for mental health.", "answer": "false", "explanation": "\"Doctors generally agree that regular physical activity is good for the heart and for mental health.\"", "skill": "reading.detail"}, {"id": "g1", "type": "gap", "prompt": "Complete the summary with words from the box.", "text": "Many people find it hard to make time for ___. Cycling to work makes exercise part of their daily ___. But very hot or cold weather, fast cars and offices with nowhere to take a ___ can stop people from cycling.", "answers": [["exercise"], ["routine"], ["shower"]], "word_bank": ["exercise", "routine", "shower", "fuel", "journey", "traffic"], "explanation": "\"Many people say they find it hard to make time for exercise… the exercise becomes part of the daily routine.\" \"Some offices have nowhere to park a bike or take a shower.\"", "skill": "reading.detail"}]'::jsonb),
    ('b2-what-sleep-does-for-memory', '[{"id": "t1", "type": "tfng", "prompt": "Researchers use the word \"consolidation\" for the process that makes new memories stable.", "answer": "true", "explanation": "\"…that memory has to be stabilised, a process researchers call consolidation.\"", "skill": "reading.detail"}, {"id": "t2", "type": "tfng", "prompt": "According to the text, enough sleep can replace studying.", "answer": "false", "explanation": "\"This does not mean that sleep can replace studying.\"", "skill": "reading.detail"}, {"id": "t3", "type": "tfng", "prompt": "Madina did badly in her exam.", "answer": "not_given", "explanation": "The text describes Madina the night before the exam. It never says how she did.", "skill": "reading.detail"}, {"id": "t4", "type": "tfng", "prompt": "Scientists agree about every detail of how sleep helps memory.", "answer": "false", "explanation": "\"Scientists are still debating many of the details.\"", "skill": "reading.detail"}, {"id": "g1", "type": "gap", "prompt": "Complete the summary. Use ONE word from the text in each gap.", "text": "A new memory is ___ at first. Much of the work that makes it stable happens at night, especially during ___ sleep, when the brain seems to replay recent experiences. So learners should ___ their revision over several days and keep a regular sleep ___.", "answers": [["fragile"], ["deep"], ["spread"], ["routine"]], "explanation": "\"A memory that is still fragile\"; \"During deep sleep, the brain appears to replay recent experiences\"; \"spread revision over several days\"; \"a regular sleep routine\".", "skill": "reading.detail"}]'::jsonb),
    ('b2-the-hidden-life-of-a-bazaar', '[{"id": "t1", "type": "tfng", "prompt": "Gulnora has a fixed price list for her fruit and nuts.", "answer": "false", "explanation": "\"She does not have a price list.\"", "skill": "reading.detail"}, {"id": "t2", "type": "tfng", "prompt": "Gulnora sees bargaining as a kind of conversation.", "answer": "true", "explanation": "\"It''s a conversation,\" she says.", "skill": "reading.detail"}, {"id": "t3", "type": "tfng", "prompt": "Most of Gulnora''s money comes from tourists.", "answer": "false", "explanation": "\"What keeps Gulnora''s business going is not tourists but regular customers.\"", "skill": "reading.detail"}, {"id": "t4", "type": "tfng", "prompt": "The bazaar is busier than the supermarkets nearby.", "answer": "not_given", "explanation": "The text says the bazaar remains busy, but it does not compare it with how busy supermarkets are.", "skill": "reading.detail"}]'::jsonb),
    ('c1-the-myth-of-the-natural-polyglot', '[{"id": "y1", "type": "tfng", "variant": "yes_no", "prompt": "The writer believes that all learners have exactly the same natural ability.", "answer": "false", "explanation": "\"I do not mean that people are identical. Some learners clearly have a better ear for sounds…\"", "skill": "reading.inference"}, {"id": "y2", "type": "tfng", "variant": "yes_no", "prompt": "The writer thinks the child from Tashkent owes her languages more to her environment than to talent.", "answer": "true", "explanation": "\"Talent did not create those hours; her environment did.\"", "skill": "reading.inference"}, {"id": "y3", "type": "tfng", "variant": "yes_no", "prompt": "The writer suggests the myth of talent survives partly because it is flattering.", "answer": "true", "explanation": "\"It is more flattering to believe that the successful have been touched by something special…\"", "skill": "reading.inference"}, {"id": "y4", "type": "tfng", "variant": "yes_no", "prompt": "The writer has taught languages in Tashkent for many years.", "answer": "not_given", "explanation": "The writer says \"in my experience\" but never says where, or for how long, they have taught.", "skill": "reading.inference"}]'::jsonb)
),
articles as (
  select a.id, a.questions, x.questions as extra
  from public.reading_articles a
  join additions x on x.slug = a.slug
  join public.languages l on l.id = a.language_id and l.code = 'en'
)
update public.reading_articles a
set questions = coalesce(a.questions, '[]'::jsonb) || coalesce((
      select jsonb_agg(item order by ord)
      from jsonb_array_elements(articles.extra) with ordinality as e(item, ord)
      where not exists (
        select 1 from jsonb_array_elements(coalesce(a.questions, '[]'::jsonb)) old
        where old->>'id' = item->>'id'
      )
    ), '[]'::jsonb),
    updated_at = now()
from articles
where articles.id = a.id
  and exists (
    select 1 from jsonb_array_elements(articles.extra) e(item)
    where not exists (
      select 1 from jsonb_array_elements(coalesce(a.questions, '[]'::jsonb)) old
      where old->>'id' = e.item->>'id'
    )
  );
